fn main() { // 3 路：0=激光(10Hz,100ms), 1=相机(约30Hz), 2=雷达。容差 15ms。 let mut buf: TimeSyncBuffer<&str> = TimeSyncBuffer::new(3, 15_000_000, 100); // slop = 15ms // 模拟消息按时间到达（时间戳单位：纳秒）。 let ms = 1_000_000u64; let events = [ (0, 100 * ms, "lidar@100"), (1, 103 * ms, "cam@103"), (2, 108 * ms, "radar@108"), // 三者跨度 8ms < 15ms，应成组 (1, 133 * ms, "cam@133"), // 下一帧相机 (0, 200 * ms, "lidar@200"), (2, 205 * ms, "radar@205"), (1, 210 * ms, "cam@210"), // 又一组，跨度 10ms ]; for (stream, stamp_ns, tag) in events { let groups = buf.push(stream, Stamped { stamp_ns, data: tag }); for g in groups { let tags: Vec<&str> = g.iter().map(|m| m.data).collect(); let span = g.iter().map(|m| m.stamp_ns).max().unwrap() - g.iter().map(|m| m.stamp_ns).min().unwrap(); println!("对齐帧组: {:?} (跨度 {} ms)", tags, span / ms); } }
} 预期输出： 对齐帧组: ["lidar@100", "cam@103", "radar@108"] (跨度 8 ms)
对齐帧组: ["lidar@200", "cam@210", "radar@205"] (跨度 10 ms) 那条 cam@133 呢？它被正确地丢弃了——因为 lidar@200 一来，cam@133 和它跨度 67 ms 远超容差，且 133 比 200 老，永远配不上后面的激光，被 try_match 里的"丢最老"逻辑清掉了。这正是我们想要的行为。 中高级视角 ：这个缓冲区是 同步 风格（凑齐才输出）。真实系统里它常和异步运行时结合——每路传感器是一个 tokio 任务往 channel 里灌消息，一个对齐任务消费。第 2.5 节的 channel 和第八部分的中间件，讲的就是消息怎么在节点间流动。对齐逻辑本身不变，变的是消息从哪来、结果发到哪去。

