pub enum PixelFormat { Rgb8, // 每像素 3 字节 Bgr8, Gray8, // 每像素 1 字节 Yuyv, // 每 2 像素 4 字节
} impl PixelFormat { /// 每像素字节数（YUYV 用平均值表达，实际按 2 像素一组）。 pub fn bytes_per_pixel(&self) -> usize { match self { PixelFormat::Rgb8 | PixelFormat::Bgr8 => 3, PixelFormat::Gray8 => 1, PixelFormat::Yuyv => 2, } }
} #[derive(Debug, Clone)]
pub struct ImageFrame { pub width: u32, pub height: u32, pub format: PixelFormat, /// 行优先像素缓冲。行与行之间可能有对齐填充，故显式存 step。 pub data: Vec<u8>, pub step: usize, // 每行字节数（>= width * bytes_per_pixel）
} impl ImageFrame { /// 借用某一行的像素，零拷贝。返回切片，不复制数据。 pub fn row(&self, y: u32) -> &[u8] { let start = y as usize * self.step; let len = self.width as usize * self.format.bytes_per_pixel(); &self.data[start..start + len] }
