use image::{DynamicImage, GenericImageView}; fn load_and_inspect(path: &str) -> Result<DynamicImage> { // open 会根据扩展名/魔数自动判断格式并解码 let img = image::open(path)?; let (w, h) = img.dimensions(); println!("尺寸: {w}x{h}, 颜色类型: {:?}", img.color()); Ok(img)
} fn main() -> Result<()> { let img = load_and_inspect("frame.jpg")?; // 统一转成 RGB8：每像素 3 个 u8，丢掉可能存在的 alpha 通道 let rgb = img.to_rgb8(); // 存成 PNG（无损，调试时看着方便） rgb.save("out.png")?; Ok(())
} DynamicImage 是个枚举，能装下灰度/RGB/RGBA/16 位等各种像素类型。实际写推理代码时， 第一步几乎总是 to_rgb8() ——把杂七杂八的输入统一成"每像素 3 个 u8、RGB 顺序"的 RgbImage，后面的处理就有了确定的假设。 访问单个像素、遍历所有像素： use image::RgbImage; fn brightness_stats(img: &RgbImage) -> (f64, u8, u8) { let mut sum = 0u64; let mut min = 255u8; let mut max = 0u8; // enumerate_pixels 给出 (x, y, &Rgb)，注意 x 是列、y 是行 for (_x, _y, px) in img.enumerate_pixels() { // 粗略亮度：三通道平均 let lum = ((px[0] as u16 + px[1] as u16 + px[2] as u16) / 3) as u8; sum += lum as u64; min = min.min(lum); max = max.max(lum); } let n = (img.width() * img.height()) as f64; (sum as f64 / n, min, max)
} 注意 image 用 (x, y) 约定：x 是列（对应宽 W）、y 是行（对应高 H）。这和数学里习惯的 (row, col) 正好反过来，是另一个经典 off-by-混乱源。 心里始终清楚：x↔宽↔col，y↔高↔row。

262.body:
use image::imageops::FilterType;
use image::RgbImage; /// 把图像缩放到目标尺寸。FilterType 决定插值方式：
/// - Nearest：最快、最糙（最近邻）
/// - Triangle：双线性，速度/质量平衡，推理前处理常用
/// - CatmullRom / Lanczos3：更平滑但更慢
fn resize_to(img: &RgbImage, w: u32, h: u32) -> RgbImage { image::imageops::resize(img, w, h, FilterType::Triangle)
} 这里藏着一个必须知道的坑 ：直接 resize 到 640×640 会 改变长宽比 ，把 1920×1080 的宽车压成方的，物体形状变形，检测精度会掉。工业界标准做法是 letterbox（信箱式缩放） ：等比例缩放到能塞进目标框，剩下的边用灰色（常用 114）填充。YOLO 系列全用这套。我们后面讲坐标映射时会把 letterbox 完整实现，因为 它同时决定了坐标怎么映射回原图 。

263.body:
有时你不想处理整张图，只关心一块 感兴趣区域（ROI, Region of Interest） ——比如已经知道红绿灯大概在图像上部中央，就只裁那一块喂给红绿灯识别网络，省算力也更准。 use image::{RgbImage, imageops}; /// 从原图裁出一个 ROI（左上角 x,y，宽 w 高 h）。
/// 会自动裁到图像边界内，避免越界。
fn crop_roi(img: &RgbImage, x: u32, y: u32, w: u32, h: u32) -> RgbImage { let x = x.min(img.width().saturating_sub(1)); let y = y.min(img.height().saturating_sub(1)); let w = w.min(img.width() - x); let h = h.min(img.height() - y); imageops::crop_imm(img, x, y, w, h).to_image()
} crop_imm 返回的是个借用视图（不拷贝），.to_image() 才真正拷出一份独立图像。真实项目里如果只是要读一块区域喂给下一步，能不 .to_image() 就别拷——每帧省一次 memcpy，累积起来很可观。

