概念说再多不如看一眼它长什么样。在真上 ROS 2 之前，我们用纯 Rust 的 channel 手搓一个 进程内 的 pub/sub，让你对"发布者不认识订阅者""一份数据多个消费者""大数据靠 Arc 零拷贝"这几件事有肌肉记忆。这段代码可直接编译运行（只依赖标准库）。 use std::collections::HashMap;
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration; /// 沿用第 1.3 节的 Obstacle（精简版）。
#[derive(Debug, Clone)]
struct Obstacle { id: u32, position: [f64; 3], velocity: [f64; 3],
} /// 一帧感知输出。用 Arc 包起来：多个订阅者共享同一份，不拷贝——
/// 这就是"进程内传大数据几乎免费"的关键。
type ObstacleFrame = Arc<Vec<Obstacle>>; /// 极简的话题总线：按话题名维护一组订阅者的发送端。
#[derive(Default)]
struct Bus { subscribers: Mutex<HashMap<String, Vec<Sender<ObstacleFrame>>>>,
} impl Bus { /// 订阅一个话题，拿到一个接收端。发布者完全不知道谁调了它。 fn subscribe(&self, topic: &str) -> Receiver<ObstacleFrame> { let (tx, rx) = channel(); self.subscribers .lock() .unwrap() .entry(topic.to_string()) .or_default() .push(tx); rx } /// 发布：把这一帧分发给该话题的所有订阅者。注意只 clone 了 Arc（引用计数+1）， /// 底层那一大片障碍物数据一次都没被拷贝。 fn publish(&self, topic: &str, frame: ObstacleFrame) { if let Some(subs) = self.subscribers.lock().unwrap().get(topic) { for tx in subs { let _ = tx.send(Arc::clone(&frame)); // 忽略"对端已退出"错误 } } }
} fn main() { let bus = Arc::new(Bus::default()); // 两个订阅者：一个当"预测"，一个当"记录"。它们互不知道对方存在。 let rx_pred = bus.subscribe("/obstacles"); let rx_log = bus.subscribe("/obstacles"); let h_pred = thread::spawn(move || { for frame in rx_pred { println!("[预测] 收到 {} 个障碍物，首个 id={}", frame.len(), frame[0].id); } }); let h_log = thread::spawn(move || { for frame in rx_log { println!("[记录] 存档一帧，含 {} 个障碍物", frame.len()); } }); // 发布者：以 10 Hz 发 3 帧就收工。它调用 publish 时对订阅者一无所知。 for seq in 0..3 { let frame: ObstacleFrame = Arc::new(vec![Obstacle { id: 42, position: [30.0, -1.5 + 0.03 * seq as f64, 0.0], velocity: [0.0, 0.3, 0.0], }]); bus.publish("/obstacles", frame); thread::sleep(Duration::from_millis(100)); } // 丢弃 bus 让 channel 关闭，两个订阅线程随之结束。 drop(bus); h_pred.join().unwrap(); h_log.join().unwrap();
} 这 100 行里藏着中间件的全部灵魂： 解耦 ：publish 里没有一个字提到"预测"或"记录"，发布者对订阅者一无所知。想加第三个订阅者（比如可视化），发布者代码一行不改。 一对多 ：一次 publish，两个订阅者各收一份。 零拷贝 ：分发时 Arc::clone 只是把引用计数加一，那片障碍物数据始终只有一份。把 Obstacle 换成 2 MB 点云，这段代码的开销 几乎不变 ——这就是 8.3 要跨进程复刻的能力。 真正的中间件（ROS 2、Zenoh）无非是把这个 Bus 做到 跨进程、跨机器 ，再加上序列化、发现、QoS、可靠重传。心智模型，就是这段代码。

