use std::time::Duration; use serde::{Deserialize, Serialize}; // 为让每个 bin 自包含，这里内联消息定义；真实项目请放进共享 lib。
#[derive(Debug, Clone, Serialize, Deserialize)]
struct Obstacle { id: u32, class: u8, position: [f64; 3], velocity: [f64; 3], size: [f64; 3], heading: f64, confidence: f32,
} #[tokio::main]
async fn main() { // 1) 打开一个 Zenoh 会话。默认配置会自动发现同网段的其他 peer。 let session = zenoh::open(zenoh::Config::default()) .await .expect("打开 zenoh 会话失败"); // 2) 声明一个发布者，绑定到 key expression "smart_driver/obstacles"。 // Zenoh 的 key 是层级化的（用 / 分隔），订阅端可以用通配符匹配。 let publisher = session .declare_publisher("smart_driver/obstacles") .await .expect("声明发布者失败"); println!("[pub] 开始以 10 Hz 发布 smart_driver/obstacles ..."); let period = Duration::from_millis(100); let dt = 0.1_f64; for seq in 0.. { // 复现第 1.3 节：前方 30m 一个正横穿的行人。 let lateral = -1.5 + 0.3 * (seq as f64) * dt; let pedestrian = Obstacle { id: 42, class: 2, position: [30.0, lateral, 0.0], velocity: [0.0, 0.3, 0.0], size: [0.5, 0.5, 1.7], heading: std::f64::consts::FRAC_PI_2, confidence: 0.92, }; // 3) 序列化成字节再 put。zenoh put 接受任何能变成 ZBytes 的东西， // 这里我们给它一段 JSON 字节。 let bytes = serde_json::to_vec(&pedestrian).expect("序列化失败"); publisher.put(bytes).await.expect("发布失败"); println!("[pub] 第 {seq} 帧：行人#42 y={:.2}m", pedestrian.position[1]); tokio::time::sleep(period).await; }
}

