use serde::{Deserialize, Serialize}; #[derive(Debug, Clone, Serialize, Deserialize)]
struct Obstacle { id: u32, class: u8, position: [f64; 3], velocity: [f64; 3], size: [f64; 3], heading: f64, confidence: f32,
} #[tokio::main]
async fn main() { let session = zenoh::open(zenoh::Config::default()) .await .expect("打开 zenoh 会话失败"); // 声明订阅者。可以用通配符，比如 "smart_driver/**" 订阅该前缀下所有话题。 let subscriber = session .declare_subscriber("smart_driver/obstacles") .await .expect("声明订阅者失败"); println!("[sub] 订阅 smart_driver/obstacles，等待数据 ..."); // recv_async 每收到一个 Sample 返回一次。Sample 里有 key、payload、时间戳等。 while let Ok(sample) = subscriber.recv_async().await { // 取出 payload 字节，反序列化回 Obstacle。 let bytes = sample.payload().to_bytes(); match serde_json::from_slice::<Obstacle>(&bytes) { Ok(ob) => { let ahead = ob.position[0]; let lateral = ob.position[1]; let lateral_v = ob.velocity[1]; let approaching = lateral * lateral_v < 0.0; if ahead > 0.0 && ahead < 50.0 && approaching { let ttc = if lateral_v.abs() > 1e-3 { lateral.abs() / lateral_v.abs() } else { f64::INFINITY }; println!( "[sub] ⚠ 障碍物#{} 前方 {:.1}m 横穿，约 {:.1}s 到车道中心 -> 减速让行", ob.id, ahead, ttc ); } else { println!("[sub] · 障碍物#{} 前方 {:.1}m，暂无风险", ob.id, ahead); } } Err(e) => eprintln!("[sub] 反序列化失败: {e}"), } }
}

