没有真车，我们用**运动学自行车模型（kinematic bicycle model）**当"世界"（第 7.1 节）。它把四轮车简化成前后两个轮子，用车速 v 和前轮转角 delta 驱动，状态是 (x, y, yaw, v)： x' = v * cos(yaw)
y' = v * sin(yaw)
yaw' = v / L * tan(delta)
v' = a # a 由油门/刹车换算 我们用最简单的前向欧拉积分推进它，步长就是控制周期。这个模型在中低速、正常转向下足够真实，是所有控制入门的标准试验台。仿真器还负责推进行人的真实运动。 # crates/sim/Cargo.toml
[package]
name = "sim"
edition.workspace = true
version.workspace = true [dependencies]
common = { path = "../common" }
perception = { path = "../perception" } // crates/sim/src/lib.rs
use common::{ControlCommand, VehicleState};
use perception::GroundTruthObstacle; /// 简易世界：自车 + 若干真值障碍物。
pub struct World { pub ego: VehicleState, pub obstacles: Vec<GroundTruthObstacle>, pub wheelbase: f64, pub max_accel: f64, pub max_brake: f64,
} impl World { /// 用一个控制指令把世界推进 dt 秒。 pub fn step(&mut self, cmd: &ControlCommand, dt: f64) { // 1) 油门/刹车 → 纵向加速度。 let a = cmd.throttle * self.max_accel - cmd.brake * self.max_brake; // 2) 自行车模型积分（前向欧拉）。 let e = &mut self.ego; e.x += e.v * e.yaw.cos() * dt; e.y += e.v * e.yaw.sin() * dt; e.yaw += e.v / self.wheelbase * cmd.steering_angle.tan() * dt; e.v = (e.v + a * dt).max(0.0); // 车不会倒车 // 3) 推进障碍物（行人匀速横穿）。 for o in &mut self.obstacles { o.position[0] += o.velocity[0] * dt; o.position[1] += o.velocity[1] * dt; } }
}

